import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Сохранения и восстановление","description":"","frontmatter":{"pageId":"players/saves-recovery","contentRevision":1},"headers":[],"relativePath":"ru/players/saves-recovery.md","filePath":"ru/players/saves-recovery.md"}'),s={name:"ru/players/saves-recovery.md"};function i(l,e,n,c,d,p){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="сохранения-и-восстановление" tabindex="-1">Сохранения и восстановление <a class="header-anchor" href="#сохранения-и-восстановление" aria-label="Permalink to &quot;Сохранения и восстановление&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Канонический сейв хранится на сервере. Дождись завершения обычного сохранения и отправки перед выходом. При обрыве переподключись: неподтверждённые операции повторяются из outbox с прежними идентификаторами, а не создаются заново.</p><p>В 0.8.1 восстановление незавершённых выдач связано с точным снимком сейва. Если игра предлагает восстановление, прочитай выбранную версию и предупреждения. Не загружай произвольный старый локальный сейв, чтобы «вернуть» уже отправленные вещи.</p><p>Если восстановление не завершается, оставь журналы на месте и передай администратору сервер, время, версию сейва и id операции. Администратор может проверить версии и выполнить контролируемый откат.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Никогда не удаляй outbox/журналы восстановления по совету случайного сообщения. Откат меняет временную линию колонии, но не является откатом всей экономики сервера.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./../admins/backup-recovery">Резервные копии и восстановление</a></li><li><a href="./troubleshooting">Проблемы игрока</a></li><li><a href="./economy">Кошелёк, почта и рынок</a></li></ul>',10)])])}const _=a(s,[["render",i]]);export{u as __pageData,_ as default};
